<script setup lang="ts">import {computed} from 'vue';import type {Event} from '../types/domain';const props=defineProps<{events:Event[];windows:number}>();const sample=computed(()=>props.events.slice(0,35));const lo=computed(()=>Math.min(...sample.value.map(e=>e.arrival)));const hi=computed(()=>Math.max(...sample.value.map(e=>e.end),lo.value+1));const x=(t:number)=>60+(t-lo.value)/(hi.value-lo.value)*510;;
</script><template><svg class="timeline" :viewBox="`0 0 600 ${windows*42+60}`" aria-label="窗口服务事件时间轴"><g v-for="s in windows" :key="s"><text x="5" :y="s*42+5">窗口{{s}}</text><line x1="60" x2="580" :y1="s*42" :y2="s*42"/></g><g v-for="e in sample" :key="e.job"><line :x1="x(e.arrival)" :x2="x(e.start)" :y1="e.server*42-9" :y2="e.server*42-9" class="waiting"/><rect :x="x(e.start)" :y="e.server*42-6" :width="Math.max(1,x(e.end)-x(e.start))" height="12"><title>样本{{e.job}}等待{{e.wait.toFixed(2)}}分钟，服务{{e.service.toFixed(2)}}分钟</title></rect></g><text x="60" :y="windows*42+42">最后一次重复 · 前35个观测期到达 · 橙线等待 / 绿块服务</text></svg></template>
